// DecodeError identifies and decodes a declared custom error.
func (c *IDiesisBundleEscrowBinding) DecodeError(raw []byte) (any, error) {
	if len(raw) < 4 {
		return nil, fmt.Errorf("revert payload is shorter than a selector")
	}
	if definition, err := c.customError("AlreadySettled()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeAlreadySettledError(raw)
	}
	if definition, err := c.customError("IncorrectReservationValue(uint256,uint256)"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeIncorrectReservationValueError(raw)
	}
	if definition, err := c.customError("NativeTransferFailed()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNativeTransferFailedError(raw)
	}
	if definition, err := c.customError("NoReservation()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNoReservationError(raw)
	}
	if definition, err := c.customError("NotExpired()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNotExpiredError(raw)
	}
	if definition, err := c.customError("NothingToWithdraw()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeNothingToWithdrawError(raw)
	}
	if definition, err := c.customError("ReservationExists()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeReservationExistsError(raw)
	}
	if definition, err := c.customError("Unauthorized()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeUnauthorizedError(raw)
	}
	if definition, err := c.customError("ZeroAddress()"); err == nil && bytes.Equal(raw[:4], definition.ID[:4]) {
		return c.DecodeZeroAddressError(raw)
	}
	return nil, fmt.Errorf("unknown custom error selector %x", raw[:4])
}
